export const blank=()=>({version:1,profile:{level:'beginner',time:55,days:2,activity:'low',goal:'recomp',equipment:['machine','cable','dumbbell','bodyweight'],excluded:[],tolerance:false},sessions:[],active:null,measurements:[],photos:[],favorites:[],overrides:{},schedule:['08:00','14:00','17:30','21:00','18:30'],reminders:false});
export function remaining(timer,now=Date.now()){return !timer?0:timer.paused?timer.left:Math.max(0,Math.ceil((timer.end-now)/1000))}
export function pauseTimer(t,now=Date.now()){return {...t,left:remaining(t,now),paused:true}}
export function resumeTimer(t,now=Date.now()){return {...t,end:now+t.left*1000,paused:false}}
export function weekNumber(s){return Math.min(12,1+Math.floor(s.sessions.filter(x=>x.complete).length/2))}
export function nextSession(s){const last=s.sessions.filter(x=>x.complete&&x.type!=='C').at(-1);return last?.type==='A'?'B':'A'}
export function recommendation(s,id,min,max){const h=s.sessions.filter(x=>x.complete).map(x=>x.logs.filter(l=>l.id===id)).filter(x=>x.length);const last=h.at(-1);if(!last)return {weight:'',text:'Sin historial: prueba una carga ligera y deja 3–4 repeticiones en reserva.'};const w=last.at(-1).weight;if(last.every(l=>l.reps>=max&&l.rir!==null&&l.rir>=2&&l.technique)&&last.length>=2)return {weight:Math.round(w*1.025*2)/2,text:'Puedes probar +2,5% si el incremento de la máquina lo permite. Prioriza técnica.'};if(last.some(l=>l.reps<min||l.rir===0))return {weight:Math.round(w*.95*2)/2,text:'Prueba mantener o reducir ~5% para recuperar el rango sin perder técnica.'};const stalled=h.length>=3&&h.slice(-3).every(l=>l.at(-1).weight===w);return {weight:w,text:stalled?'Tres exposiciones sin aumento: revisa sueño, repeticiones y recuperación; puedes activar descarga.':'Mantén la carga y suma repeticiones antes de aumentarla.'}}
export function makeSession(s,plans,type,energy,deload=false){const week=weekNumber(s),adapt=(s.profile.level==='beginner'&&week<=2)||s.profile.experience==='no';let list=structuredClone(plans[type]);const express=energy==='low'||+s.profile.time<40;if(express){const keep=type==='A'?['chest','lat','legpress','legcurl','crunch']:type==='B'?['incline','row','legcurl','legext','plank']:['incline','chestrow','legpress','legcurl','crunch'];list=list.filter(x=>keep.includes(x.id)).map(x=>({...x,sets:2}));}else if(type==='C')list=list.map(x=>({...x,sets:Math.min(x.sets,2)}));if(!express&&+s.profile.time===45)list=list.map(x=>({...x,sets:Math.min(2,x.sets)}));if(adapt||deload)list=list.map(x=>({...x,sets:Math.max(1,Math.min(2,x.sets-(deload?1:0)))}));list=list.filter(x=>!(s.profile.excluded||[]).includes(x.id));return {type,energy,express,deload,week,adapt,started:Date.now(),plan:list.map(x=>({...x,original:x.id,done:0})),index:0,logs:[],swaps:[],timer:null,warmup:false,complete:false,rir:adapt||deload||express?'3–4':'2–3'};}
export function recordSet(session,{weight,reps,rir,technique}){const s=structuredClone(session),e=s.plan[s.index];if(!e||e.done>=e.sets)throw Error('Serie no disponible');if(!Number.isFinite(weight)||weight<0||weight>1000||!Number.isFinite(reps)||reps<1||reps>600)throw Error('Revisa peso y repeticiones');s.logs.push({id:e.id,original:e.original,weight,reps,rir,technique,group:e.group??null,at:Date.now()});e.done++;s.timer={end:Date.now()+e.rest*1000,paused:false,left:e.rest};return s;}
export function advance(s){s=structuredClone(s);s.timer=null;if(s.plan[s.index].done<s.plan[s.index].sets)return s;if(s.index<s.plan.length-1)s.index++;else{s.complete=true;s.ended=Date.now()}return s}
export function validateImport(x){if(!x||x.version!==1||!Array.isArray(x.sessions)||!Array.isArray(x.measurements)||!x.profile||typeof x.profile!=='object'||Array.isArray(x.profile))throw Error('Archivo de SealGym no válido');if(x.sessions.length>10000||x.measurements.length>10000)throw Error('Archivo demasiado grande');for(const s of x.sessions){if(!['A','B','C'].includes(s.type)||!Array.isArray(s.logs)||s.logs.some(l=>typeof l.id!=='string'||!Number.isFinite(l.weight)||!Number.isFinite(l.reps)))throw Error('Historial no válido')}if(x.active&&(!Array.isArray(x.active.plan)||!Array.isArray(x.active.logs)||!Number.isInteger(x.active.index)||x.active.index<0||x.active.index>=x.active.plan.length))throw Error('Sesión no válida');return {...blank(),...x,profile:{...blank().profile,...x.profile}}}
export async function openDB(){return new Promise((resolve,reject)=>{let q=indexedDB.open('sealgym',1);q.onupgradeneeded=()=>q.result.createObjectStore('state');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error)})}
export async function readDB(db){return new Promise((resolve,reject)=>{const q=db.transaction('state').objectStore('state').get('main');q.onsuccess=()=>resolve(q.result||blank());q.onerror=()=>reject(q.error)})}
export async function saveDB(db,state){return new Promise((resolve,reject)=>{const tx=db.transaction('state','readwrite');tx.objectStore('state').put(state,'main');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
